-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(
    materialized='incremental',
    incremental_strategy=dpf_incremental_strategy({"bigquery": "merge", "duckdb": "delete+insert"}),
    unique_key=["fund_hk", "effective_from", "hashdiff_basis_version"]
) }}

with
sat_fund_detail_source as (
    select distinct
        fund_business_key,
        fund_name,
        fund_family_name,
        fund_vehicle_type,
        fund_asset_class,
        fund_strategy,
        fund_gp_business_key,
        fund_domicile,
        fund_currency,
        fund_reported_on
    from {{ ref("investment__fund_vault__base") }}
    where fund_business_key is not null
),
sat_fund_detail_fingerprinted as (
    select
        {{ dpf_vault_hash(["fund_business_key"]) }} as fund_hk,
        {{ dpf_vault_hash(["fund_name", "fund_family_name", "fund_vehicle_type", "fund_asset_class", "fund_strategy", "fund_gp_business_key"]) }} as hashdiff,
        1 as hashdiff_basis_version,
        fund_name,
        fund_family_name,
        fund_vehicle_type,
        fund_asset_class,
        fund_strategy,
        fund_gp_business_key,
        fund_domicile,
        fund_currency,
        fund_reported_on as effective_from,
        {{ dpf_publish_timestamp() }} as load_datetime,
        'investment.fund_vault' as record_source
    from sat_fund_detail_source
),
sat_fund_detail_unstored as (
    select
        fund_hk,
        hashdiff,
        hashdiff_basis_version,
        fund_name,
        fund_family_name,
        fund_vehicle_type,
        fund_asset_class,
        fund_strategy,
        fund_gp_business_key,
        fund_domicile,
        fund_currency,
        effective_from,
        load_datetime,
        record_source
    from sat_fund_detail_fingerprinted
    where {{ dpf_vault_new_versions("sat_fund_detail_fingerprinted", "fund_hk", "hashdiff", "effective_from", "hashdiff_basis_version", "current") }}
)

select
    cast(fund_hk as {{ dpf_type('string') }}) as fund_hk,
    cast(hashdiff as {{ dpf_type('string') }}) as hashdiff,
    cast(hashdiff_basis_version as {{ dpf_type('int') }}) as hashdiff_basis_version,
    cast(fund_name as {{ dpf_type('string') }}) as fund_name,
    cast(fund_family_name as {{ dpf_type('string') }}) as fund_family_name,
    cast(fund_vehicle_type as {{ dpf_type('string') }}) as fund_vehicle_type,
    cast(fund_asset_class as {{ dpf_type('string') }}) as fund_asset_class,
    cast(fund_strategy as {{ dpf_type('string') }}) as fund_strategy,
    cast(fund_gp_business_key as {{ dpf_type('string') }}) as fund_gp_business_key,
    cast(fund_domicile as {{ dpf_type('string') }}) as fund_domicile,
    cast(fund_currency as {{ dpf_type('string') }}) as fund_currency,
    cast(effective_from as {{ dpf_type('date') }}) as effective_from,
    cast(load_datetime as {{ dpf_type('timestamp') }}) as load_datetime,
    cast(record_source as {{ dpf_type('string') }}) as record_source
from sat_fund_detail_unstored
